import{_ as a,o as r,c as t,ag as o}from"./chunks/framework.B_zcDAFh.js";const m=JSON.parse('{"title":"Boing Reactor Field Sampler","description":"","frontmatter":{},"headers":[],"relativePath":"guide/boing-reactor-field-sampler.md","filePath":"guide/boing-reactor-field-sampler.md"}'),i={name:"guide/boing-reactor-field-sampler.md"};function s(n,e,l,d,p,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="boing-reactor-field-sampler" tabindex="-1">Boing Reactor Field Sampler <a class="header-anchor" href="#boing-reactor-field-sampler" aria-label="Permalink to &quot;Boing Reactor Field Sampler&quot;">​</a></h1><p>A sampler reads from a <a href="./boing-reactor-field.html">Boing Reactor Field</a> and applies the field&#39;s influence to a target. This is how individual objects (or mesh vertices) cheaply pick up the field&#39;s reaction without each owning a full reactor.</p><p>Two variants ship with the kit:</p><ul><li><strong>CPU Sampler</strong> (<code>BoingReactorFieldCPUSampler</code>) — a component that samples on the CPU and writes the result to the object&#39;s transform. Use when the field is set to <code>Hardware Mode = CPU</code>.</li><li><strong>GPU Sampler</strong> (<code>BoingReactorFieldGPUSampler</code>) — a component that wires the field as shader resources so a vertex shader can sample it per object or per vertex. Use when the field is set to <code>Hardware Mode = GPU</code>. Suited to instanced meshes and dense vertex counts.</li></ul><h2 id="gpu-sampling" tabindex="-1">GPU Sampling <a class="header-anchor" href="#gpu-sampling" aria-label="Permalink to &quot;GPU Sampling&quot;">​</a></h2><p>The object&#39;s material must use a vertex shader that calls one of the helpers Boing Kit provides:</p><ul><li><code>ApplyBoingReactorFieldPerObject</code> — one sample per object (cheap, uniform deformation).</li><li><code>ApplyBoingReactorFieldPerVertex</code> — one sample per vertex (fine-grained deformation).</li></ul><p>The kit ships example HLSL shaders (built-in pipeline) that already wire these in. For custom vertex shaders, see the <strong>Example Custom Shader</strong> files in the <em>Warped Teapots</em> example.</p><h2 id="urp-and-hdrp" tabindex="-1">URP and HDRP <a class="header-anchor" href="#urp-and-hdrp" aria-label="Permalink to &quot;URP and HDRP&quot;">​</a></h2><p>For shader graphs, use the <strong>shader subgraph</strong> under <code>Shader/</code> — it wraps the same helpers in node form so you can drop it into your URP/HDRP graphs. The built-in render pipeline uses the HLSL include path; the SRP variants use the subgraph.</p>',10)])])}const u=a(i,[["render",s]]);export{m as __pageData,u as default};
